import { prisma } from "@/lib/prisma";
import { statusLabel } from "@/lib/status-labels";
import { formatChinaDateTime } from "@/lib/time";
import { EmptyState } from "@/components/ui/empty-state";
import { FilterActions, FilterClearLink, FilterField, FilterSelectField, FilterTextField, ListFilter, Pagination, ResultSummary } from "@/components/ui/list";
import { RecordCard, RecordCardField, RecordCardFields, RecordCardHeader, RecordCardList } from "@/components/ui/record-card";
import { StatusBadge } from "@/components/ui/status-badge";
import { Button } from "@/components/ui/button";
import { PageHeader } from "@/components/ui/page-header";
import styles from "./page.module.css";
const pageSize=50; type Search={q?:string;status?:string;page?:string}; const href=(input:Search,page:number)=>{const p=new URLSearchParams();if(input.q)p.set("q",input.q);if(input.status)p.set("status",input.status);p.set("page",String(page));return `/containers?${p}`};
export default async function Containers({searchParams}:{searchParams:Promise<Search>}){const input=await searchParams,q=input.q||"",status=input.status||"ACTIVE",requested=Math.max(1,Number(input.page)||1),term=q.trim(),where={...(status==="ALL"?{}:{active:status==="ACTIVE"}),...(term?{OR:[{internalCode:{contains:term,mode:"insensitive" as const}},{containerNo:{contains:term,mode:"insensitive" as const}},{soOrder:{soNumber:{contains:term,mode:"insensitive" as const}}}]}:{})};const total=await prisma.containerUnit.count({where}),totalPages=Math.max(1,Math.ceil(total/pageSize)),currentPage=Math.min(requested,totalPages);const containers=await prisma.containerUnit.findMany({where,include:{soOrder:{select:{id:true,soNumber:true,status:true}},planItems:{where:{active:true},include:{loadingPlan:{include:{factory:true}}}}},orderBy:{internalCode:"asc"},skip:(currentPage-1)*pageSize,take:pageSize});return <><PageHeader title="柜子管理" description="查看每个柜子的所属订单与装柜安排。实际柜号可在订单详情中补充。"/><ListFilter className={styles.filter}><FilterField label="查找柜子或订单" search><FilterTextField name="q" defaultValue={q}/></FilterField><FilterField label="显示范围"><FilterSelectField name="status" defaultValue={status}><option value="ACTIVE">在用柜子</option><option value="INACTIVE">已停用柜子</option><option value="ALL">全部柜子</option></FilterSelectField></FilterField><FilterActions className={styles.filterActions}><Button type="submit">查看柜子</Button><FilterClearLink href="/containers" /></FilterActions></ListFilter><ResultSummary className={styles.resultSummary}>共 {total} 个柜子，第 {currentPage} / {totalPages} 页。</ResultSummary><RecordCardList className={styles.list} density="compact">{containers.length?containers.map(c=>{const plan=c.planItems[0]?.loadingPlan;return <RecordCard density="compact" className={c.active?undefined:styles.inactive} key={c.id}><RecordCardHeader density="compact" className={styles.header}><div><span className={styles.label}>内部柜号</span><b>{c.internalCode}</b></div><StatusBadge tone={c.active?"success":"muted"}>{c.active?"在用":"已停用"}</StatusBadge></RecordCardHeader><RecordCardFields density="compact" columns={4} className={styles.body}><RecordCardField density="compact"><span className={styles.label}>实际柜号</span><b>{c.containerNo||"待补充"}</b></RecordCardField><RecordCardField density="compact"><span className={styles.label}>柜型</span><b>{c.containerType}</b></RecordCardField><RecordCardField density="compact"><span className={styles.label}>所属订单</span><a href={`/orders/${c.soOrder.id}`}>{c.soOrder.soNumber}</a><span>{statusLabel(c.soOrder.status)}</span></RecordCardField><RecordCardField density="compact" fullOnMobile className={styles.plan}><span className={styles.label}>装柜安排</span>{plan?<><b>{plan.factory.name}</b><span>{formatChinaDateTime(plan.scheduledAt)}</span></>:<span>尚未安排装柜</span>}</RecordCardField></RecordCardFields></RecordCard>}):<EmptyState title="未找到柜子">可尝试更换柜号、SO 编号或显示范围。</EmptyState>}</RecordCardList><Pagination currentPage={currentPage} totalPages={totalPages} href={page=>href(input,page)} label="柜子分页"/></>}
